// Turns a message from the site broker into the gateway's input format.
// Each protocol has its own adapter: see "Adding a protocol" in README.md.
// Out: msg.source = { protocol, siteId, sensorId }, msg.payload unchanged
const parts = String(msg.topic).split("/");
const valid = parts.length === 4 && parts[0] === "coldtrace" && parts[3] === "telemetry";
msg.source = valid ? { protocol: "mqtt", siteId: parts[1], sensorId: parts[2] } : { protocol: "mqtt" };
return msg;

// Checks one sensor message and turns it into the standard ColdTrace format.
// In:  msg.source  = { protocol, siteId, sensorId }, set by the protocol adapter
//      msg.payload = the sensor's data (JSON text, Buffer or object)
// Out 1: a clean reading (goes on to the cloud)
// Out 2: a rejected message, with msg.reason explaining why

const GATEWAY_ID = env.get("GATEWAY_ID") || "gw-unknown";
const LIMITS = {
    temperature: [-40, 85],   // °C, the sensor's physical range
    humidity:    [0, 100]     // %
};
const ID_RE = /^[A-Za-z0-9_-]{1,32}$/;

function reject(reason) {
    const stats = flow.get("stats") || {};
    stats.rejected = (stats.rejected || 0) + 1;
    flow.set("stats", stats);
    msg.reason = `${(msg.source && msg.source.protocol) || "unknown"}: ${reason}`;
    return [null, msg];
}

function toNumber(v) {
    if (typeof v === "number") return v;
    if (typeof v === "string" && v.trim() !== "") return Number(v);
    return NaN;
}

function toBool(v) {
    if (v === true || v === 1 || v === "1" || v === "true" || v === "open") return true;
    if (v === false || v === 0 || v === "0" || v === "false" || v === "closed") return false;
    return null;
}

// 1. Source: which site and which sensor
const { siteId, sensorId } = msg.source || {};
if (typeof siteId !== "string" || typeof sensorId !== "string") return reject("no site or sensor id");
if (!ID_RE.test(siteId) || !ID_RE.test(sensorId)) return reject("bad site or sensor id");

// 2. Payload must be a JSON object
let data = msg.payload;
if (typeof data === "string" || Buffer.isBuffer(data)) {
    try { data = JSON.parse(data.toString()); } catch (e) { return reject("payload is not JSON"); }
}
if (!data || typeof data !== "object" || Array.isArray(data)) return reject("payload must be a JSON object");

// 3. Measurements (short names "temp", "hum", "door" are accepted too)
const reading = {};
for (const [field, alias] of [["temperature", "temp"], ["humidity", "hum"]]) {
    const raw = data[field] !== undefined ? data[field] : data[alias];
    if (raw === undefined || raw === null) continue;
    const n = toNumber(raw);
    if (!Number.isFinite(n)) return reject(field + " is not a number");
    const [min, max] = LIMITS[field];
    if (n < min || n > max) return reject(`${field} ${n} outside ${min}..${max}`);
    reading[field] = Math.round(n * 10) / 10;
}
const rawDoor = data.doorOpen !== undefined ? data.doorOpen : data.door;
if (rawDoor !== undefined && rawDoor !== null) {
    const b = toBool(rawDoor);
    if (b === null) return reject("doorOpen must be true or false");
    reading.doorOpen = b;
}
if (Object.keys(reading).length === 0) return reject("no temperature, humidity or doorOpen");

// 4. Time: use the sensor's time if it looks right, otherwise the gateway's.
// (An ESP32 without NTP would send a time in 1970.)
const now = Date.now();
let ts = NaN;
if (typeof data.ts === "number") ts = data.ts < 1e12 ? data.ts * 1000 : data.ts;  // seconds or ms
else if (typeof data.ts === "string") ts = Date.parse(data.ts);
let tsSource = "sensor";
const FIVE_MIN = 5 * 60 * 1000, SEVEN_DAYS = 7 * 24 * 3600 * 1000;
if (!Number.isFinite(ts) || ts > now + FIVE_MIN || ts < now - SEVEN_DAYS) {
    ts = now;
    tsSource = "gateway";
}
ts = Math.round(ts);

msg.payload = {
    v: 1,
    msgId: `${siteId}-${sensorId}-${ts}`,
    siteId,
    sensorId,
    gatewayId: GATEWAY_ID,
    ts: new Date(ts).toISOString(),
    tsSource,
    ...reading,
    receivedAt: new Date(now).toISOString()
};
msg.topic = `coldtrace/${siteId}/${sensorId}/telemetry`;
return [msg, null];

// Sends readings to the cloud, or keeps them while the cloud is unreachable.
// It receives three kinds of messages:
//   - msg.status        : the cloud MQTT node changed state (connected or not)
//   - topic "replay"    : timer tick, send the next batch of kept readings
//   - anything else     : a new clean reading
// The buffer is saved in the "file" context store, so it survives a restart.
// Readings always leave in order: while old ones are waiting, new ones queue behind them.

const MAX = Number(env.get("BUFFER_MAX")) || 20000;
const BATCH = Number(env.get("REPLAY_BATCH")) || 50;
const STORE = "file";

const stats = flow.get("stats") || {};
let buffer = flow.get("buffer", STORE) || [];

function showStatus(online) {
    node.status({
        fill: online ? (buffer.length ? "yellow" : "green") : "red",
        shape: "dot",
        text: (online ? "cloud online" : "cloud offline") + ` | buffered: ${buffer.length}`
    });
}
function bump(name, n) { stats[name] = (stats[name] || 0) + n; flow.set("stats", stats); }
function toMsg(reading, replayed) {
    return {
        topic: `coldtrace/${reading.siteId}/${reading.sensorId}/telemetry`,
        payload: replayed ? { ...reading, replayed: true } : reading
    };
}

// 1. Connection state of the cloud broker
if (msg.status) {
    const online = msg.status.fill === "green";
    if (online !== flow.get("cloudOnline")) {
        node.log(online ? `cloud connected, ${buffer.length} readings to replay`
                        : "cloud disconnected, buffering readings");
    }
    flow.set("cloudOnline", online);
    showStatus(online);
    return null;
}

const online = flow.get("cloudOnline") === true;

// 2. Timer: replay a batch of kept readings
if (msg.topic === "replay") {
    if (online && buffer.length > 0) {
        const batch = buffer.splice(0, BATCH);
        flow.set("buffer", buffer, STORE);
        bump("replayed", batch.length);
        node.send([batch.map(r => toMsg(r, true))]);
        if (buffer.length === 0) node.log("replay finished");
    }
    showStatus(online);
    return null;
}

// 3. New reading
if (online && buffer.length === 0) {
    bump("forwarded", 1);
    showStatus(online);
    return toMsg(msg.payload, false);
}
buffer.push(msg.payload);
if (buffer.length > MAX) {
    // Full: drop the oldest so the newest data is kept
    const extra = buffer.length - MAX;
    buffer.splice(0, extra);
    bump("dropped", extra);
}
flow.set("buffer", buffer, STORE);
showStatus(online);
return null;

// Every minute: tell the cloud the gateway is alive, with a few counters.
// Sent only when the cloud is reachable (a late heartbeat is useless).
if (flow.get("cloudOnline") !== true) return null;
const buffer = flow.get("buffer", "file") || [];
const stats = flow.get("stats") || {};
msg.topic = env.get("GATEWAY_STATUS_TOPIC");
msg.retain = true;
msg.payload = {
    v: 1,
    gatewayId: env.get("GATEWAY_ID"),
    siteId: env.get("SITE_ID"),
    status: "online",
    ts: new Date().toISOString(),
    buffered: buffer.length,
    forwarded: stats.forwarded || 0,
    replayed: stats.replayed || 0,
    rejected: stats.rejected || 0,
    dropped: stats.dropped || 0
};
return msg;
